import type { LensFinding } from "./skeptic.ts";

const RANK = { high: 3, medium: 2, low: 1 } as const;
const LENS = ["conventions", "incidents", "requirements", "correctness", "security"];
const norm = (title: string) => title.toLowerCase().replace(/[^a-z0-9 ]/g, "").trim();
const better = (a: LensFinding, b: LensFinding) =>
  RANK[a.severity] - RANK[b.severity] || RANK[a.confidence] - RANK[b.confidence] || LENS.indexOf(a.lens) - LENS.indexOf(b.lens);

export const dedupe = (findings: LensFinding[]): LensFinding[] => {
  const kept: LensFinding[] = [];
  for (const f of findings) {
    const i = kept.findIndex((k) => k.path === f.path && norm(k.title) === norm(f.title) && Math.abs(k.line - f.line) <= 5);
    if (i === -1) kept.push(f);
    else if (better(f, kept[i]) > 0) kept[i] = f;
  }
  return kept;
};

const base = { path: "src/ProjectsTable.tsx", confidence: "high" as const, title: "Empty card shows while loading!" };
console.log(dedupe([{ ...base, lens: "correctness", line: 10, severity: "medium" }, { ...base, lens: "security", line: 14, severity: "high", title: "empty card shows while loading" }]).map((f) => `${f.lens}:${f.line}:${f.severity}`));
console.log(dedupe([{ ...base, lens: "correctness", line: 10, severity: "medium" }, { ...base, lens: "security", line: 20, severity: "high" }]).length);
// [ 'security:14:high' ]
// 2
